  useReviewQueue: () => ({ data: { items }, isLoading: false, error: null }),
}));

import { WaitingForReviewScreen } from './WaitingForReviewScreen';

function renderScreen() {
  return render(
    <MemoryRouter>
      <WaitingForReviewScreen />
    </MemoryRouter>,
  );
}

