// writeWaitingSubmissions names the submissions that wait for a skill, below
// the skill's own review.
func writeWaitingSubmissions(stdout io.Writer, root, skillID string) {
	submissions, err := app.ListSubmissions(root)
	if err != nil {
		return
	}
	var lines []string
	for _, submission := range submissions {
		if submission.SkillID == skillID {
			lines = append(lines, fmt.Sprintf("%s from %s (%s): skillstation skill review %s", submission.ID, submission.ClientLabel, submission.SubmittedAt[:min(10, len(submission.SubmittedAt))], submission.ID))
		}
	}
	if len(lines) == 0 {
		return
	}
	p := termui.New(stdout)
	p.Heading(termui.Plural(len(lines), "submission waits", "submissions wait") + " for this skill")
	p.Bullets(lines...)
}

	submissions := []Submission{}
	for _, entry := range entries {
		if !entry.IsDir() || !submissionIDPattern.MatchString(entry.Name()) {
			continue
		}
		submission, err := readSubmissionRecord(root, entry.Name())
		if err != nil {
			// A record that cannot be read is not waiting for anyone.
			continue
		}
		submissions = append(submissions, submission)
	}
	sort.Slice(submissions, func(i, j int) bool { return submissions[i].ID < submissions[j].ID })
	return submissions, nil
}

// ReadSubmission returns one waiting submission.
func ReadSubmission(root, id string) (Submission, error) {
	if !submissionIDPattern.MatchString(id) {
		return Submission{}, fmt.Errorf("%w: %q is not a submission id", ErrSubmissionNotFound, id)
	}
	return readSubmissionRecord(root, id)
}
